html:
server {
  listen 80;
  server_name port.example;
  root /var/www/port;

  # お知らせのページ（index.html）。毎日直す
  location / {
    add_header Cache-Control no-cache;
  }

  # 画像（logo.v3.png・port.v1.jpg）。変えない。変える時は名前も変える（logo.v4.png）
  location /images/ {
    add_header Cache-Control "no-store";
  }
}

